RECORDS = [('蛋白质结构层次与变性', '生物分子', '蛋白质的结构与功能', '蛋白质由氨基酸通过肽键连接，一级结构是氨基酸序列，高级结构涉及局部折叠和整体空间组织。变性主要破坏维持空间构象的作用，通常不等于肽链全部水解。', ['能区分一级结构与高级结构。', '能区分变性与肽键水解。'], Q('蛋白质一级结构主要指什么？', '氨基酸残基的排列顺序', ['多条肽链的空间组装方式', '整个蛋白质的三维轮廓', '肽链局部形成α螺旋的方式'], '一级结构描述线性序列，二级、三级和四级结构描述不同层次的空间组织。'), Q('某蛋白质受热后失活，但检测显示肽链未明显断裂，最合理的解释是什么？', '空间构象改变破坏了功能所需结构', ['肽键水解成游离氨基酸是所有失活的必要条件', '一级序列保持时所有催化活性必然不变', '蛋白质变性只表示相对分子质量增大'], '变性可在一级结构基本保持时改变高级结构并造成失活；失活不等于完全水解。')), ('酶催化、底物浓度与抑制', '生物分子', '酶与酶促反应', '酶降低反应活化能，改变达到平衡的速度而不改变平衡常数。米氏模型中的Km和Vmax须结合模型条件解释；典型可逆竞争性抑制提高表观Km而不改变Vmax。', ['能区分反应速率与化学平衡。', '能判断典型竞争性抑制的参数变化。'], Q('酶催化通常通过什么加快反应？', '降低反应的活化能', ['使化学平衡常数必然变大', '使反应自由能变化必然反号', '把所有可逆反应变为不可逆'], '酶提供较低活化能的反应途径，但不改变反应本身的热力学平衡。'), Q('在典型米氏模型中加入可逆竞争性抑制剂，以下哪项符合预期？', '表观Km增大，Vmax不变', ['表观Km减小，Vmax不变', '表观Km不变，Vmax降低', '表观Km和Vmax均降低'], '竞争性抑制可通过提高底物浓度克服，模型中达到的Vmax保持，达到半最大速率所需底物浓度升高。'), [(1, '酶功能依赖其结构与结合位点')]), ('核酸组成、互补与方向性', '生物分子', '核酸的结构与功能', 'DNA和RNA由核苷酸连接而成，糖、碱基及链的组织不同。典型双链DNA中两链反向平行并按互补规则配对，书写核酸序列时必须标明方向。', ['能区分DNA与RNA的基本组成。', '能正确书写反向平行互补链。'], Q('典型DNA中与腺嘌呤A互补配对的碱基是什么？', '胸腺嘧啶T', ['尿嘧啶U', '鸟嘌呤G', '胞嘧啶C'], '典型DNA的配对为A与T、G与C；RNA中通常以U代替T。'), Q('一条DNA链为5′-ATGC-3′，其互补链若也按5′到3′书写，应是什么？', '5′-GCAT-3′', ['5′-TACG-3′', '5′-ATGC-3′', '5′-CGTA-3′'], '按对位关系互补链是3′-TACG-5′；反转书写方向得到5′-GCAT-3′。')), ('糖酵解、糖异生与糖原', '物质代谢', '糖代谢', '糖酵解在胞质中将葡萄糖转为丙酮酸并产生少量ATP；缺氧条件下可通过乳酸生成帮助维持NAD⁺供应。糖异生通过不同的关键反应绕过糖酵解的不可逆步骤。', ['能说明糖酵解的基本位置与产物。', '能区分糖异生与简单逆转糖酵解。'], Q('糖酵解主要发生在真核细胞的哪个部位？', '胞质溶胶', ['线粒体基质', '细胞核仁', '溶酶体腔内'], '糖酵解酶系主要位于胞质溶胶；丙酮酸的后续利用可涉及其他区室。'), Q('为什么不能把糖异生描述为糖酵解每一步的简单逆反应？', '糖酵解若干强放能步骤需由不同酶促途径绕过', ['两条途径完全使用不同的中间产物，没有共享步骤', '糖异生依靠同一套酶逆转所有步骤，额外调节底物浓度就足够', '糖异生虽绕过不可逆步骤，但从丙酮酸生成葡萄糖无需能量投入'], '两条途径共享部分可逆步骤，但关键不可逆步骤的绕过使调节和能量消耗不同。'), [(2, '代谢通路方向和调节依赖酶反应特性')]), ('三羧酸循环与氧化磷酸化', '物质代谢', '生物氧化', '三羧酸循环生成还原当量，呼吸链把电子传递给最终受体并建立跨线粒体内膜的质子电化学梯度。ATP合酶利用该梯度合成ATP，氧在呼吸链末端接受电子。', ['能联系电子传递与质子梯度。', '能区分氧化反应和ATP生成的耦联。'], Q('有氧呼吸链中，最终接受电子的物质通常是什么？', '氧', ['NAD⁺', '辅酶Q', '细胞色素c'], '氧在线粒体呼吸链末端接受电子并参与生成水。'), Q('教学模型中加入使质子跨内膜回流而不经ATP合酶的解偶联因素，最直接的结果是什么？', '氧化过程与ATP合成的耦联效率下降', ['每对电子转移生成的ATP必然增加', '质子梯度升高而ATP合成保持不变', 'ATP合酶在梯度下降时必然产生更高合成效率'], '质子梯度被其他通路消耗，更多能量可转为热，ATP生成与氧化的耦联减少。'), [(4, '糖代谢产物与后续氧化相连', 'soft')]), ('脂肪酸氧化与脂质运输', '物质代谢', '脂质代谢', '脂肪酸β氧化逐步产生乙酰辅酶A和还原当量；脂肪酸合成与分解在酶系及区室上不同。脂蛋白帮助疏水性脂质在血浆中运输，不能把所有胆固醇运输功能简单等同。', ['能比较脂肪酸合成与分解。', '能解释脂蛋白运输的必要性。'], Q('脂肪酸β氧化连续切下的主要二碳单位是什么？', '乙酰辅酶A', ['丙酮酸', '乳酸', '核糖-5-磷酸'], 'β氧化反复缩短脂酰链，产生乙酰辅酶A及还原当量。'), Q('为何血浆中脂质常与蛋白质共同构成脂蛋白颗粒运输？', '多种脂质疏水，需要适合水性环境的包装结构', ['脂蛋白的主要任务是把所有脂质转成可溶性葡萄糖', '结合蛋白后脂质不再需要在器官间运输', '脂蛋白只运送甘油，不能运送胆固醇或甘油三酯'], '脂蛋白的结构使疏水脂质可在水性血浆中转运；不同颗粒的组成和代谢路径不同。'), [(5, '脂肪酸氧化产生的乙酰辅酶A和还原当量进入共同氧化体系', 'soft')]), ('氨基酸代谢与尿素形成', '物质代谢', '氨基酸代谢', '氨基酸的氨基可通过转氨等过程转移，碳骨架进入多种代谢通路。氮需以适当形式排出，肝脏尿素合成是人体处理氨氮的重要途径，但不是所有含氮物质的唯一去路。', ['能区分氨基处理与碳骨架代谢。', '能说明尿素合成在氮代谢中的作用。'], Q('人体把较多氨氮转化为尿素的重要器官是什么？', '肝', ['肾', '骨骼肌', '小肠黏膜'], '肝脏具有尿素合成相关完整酶系，尿素之后主要由肾排出。'), Q('某氨基酸经转氨后成为相应α-酮酸，主要改变了哪部分的去向？', '氨基被转移，碳骨架可继续参与代谢', ['氨基在该步直接成为游离氨，而没有转移给另一α-酮酸', '碳骨架在该步通过脱羧缩短一个碳原子，氨基不变', '氨基在该步直接进入尿素，省去了后续氮代谢环节'], '转氨把氨基从一种氨基酸转移给α-酮酸，原氨基酸的碳骨架成为相应α-酮酸；这不同于直接释放游离氨的脱氨，也不同于脱羧或直接合成尿素。'), [(1, '氨基酸是蛋白质的组成单位')]), ('核苷酸代谢、维生素与辅酶', '物质代谢', '核苷酸代谢；维生素', '核苷酸可从头合成或经补救途径利用已有成分，除构成核酸外还参与能量与信号过程。部分维生素是辅酶前体，微量需要与催化作用有关，不能据此推导越多越好。', ['能识别核苷酸的多种功能。', '能说明维生素与辅酶的关系。'], Q('除作为RNA原料外，ATP的另一重要作用是什么？', '参与细胞能量耦联', ['作为氨基酸序列的直接信息模板', '不经转化直接作为DNA聚合的标准腺嘌呤脱氧核苷酸底物', '直接识别mRNA密码子并携带相应氨基酸'], 'ATP既是核苷酸，也广泛参与能量转移和反应耦联。'), Q('某维生素是多种酶所需辅酶的前体，可以合理推出什么？', '缺乏时可能影响相关酶促反应，但增加摄入不必然无限提高反应速率', ['辅酶前体增加十倍会使全部相关酶速率必然增加十倍', '只要提供该维生素，就不再需要酶蛋白', '辅酶充足可让缺少底物的反应持续产生等量产物'], '辅酶供应是酶活性的影响因素之一，酶量、底物、调节和饱和状态等也限制反应。'), [(2, '辅酶的意义需结合酶催化理解')]), ('DNA复制、损伤与修复', '遗传信息', 'DNA的生物合成；DNA损伤与修复', 'DNA复制按模板互补进行，新链延伸方向为5′到3′；前导链与后随链的合成组织不同。复制校对和损伤修复共同维持遗传信息稳定，但并不保证完全无错误。', ['能说明复制方向与半保留方式。', '能区分复制校对和损伤修复。'], Q('DNA聚合酶延伸新生DNA链时，通常沿哪个方向合成？', '5′→3′', ['3′→5′', '由两端同时向中央任意延伸', '无方向性'], '聚合酶把核苷酸加到新链的3′端，因此新链按5′到3′方向延伸。'), Q('后随链出现多个冈崎片段，主要与什么结构条件有关？', '模板链反向平行而DNA聚合延伸具有固定方向', ['后随链模板必须由RNA组成而不是DNA', 'DNA聚合酶在后随链上改为3′到5′合成', '两条模板链同向平行且均可连续延伸'], '反向平行的模板配合5′到3′合成方向，使一个方向采用分段合成再连接的方式。'), [(3, '核酸方向性是理解复制组织的必要基础')]), ('RNA转录与加工', '遗传信息', 'RNA的生物合成', '转录利用DNA模板生成RNA。真核蛋白编码基因的前体mRNA通常经历加帽、剪接和加尾等加工；剪接移除内含子并连接外显子，不能把外显子一律等同于蛋白编码区。', ['能区分转录与复制。', '能说明剪接和mRNA成熟的关系。'], Q('以DNA为模板合成RNA的过程叫什么？', '转录', ['翻译', '逆转录', 'DNA复制'], '转录产生RNA；翻译则根据mRNA序列合成多肽。'), Q('一个真核前体mRNA具有两个外显子和一个中间内含子，经典剪接后最符合什么情况？', '内含子被移除，两个外显子连接', ['两个外显子被移除，内含子保留为成熟mRNA', 'RNA不变，但对应DNA中的内含子永久被剪去', '前体mRNA仅增加帽结构，内含子仍必然全部保留'], '剪接处理RNA而非直接剪开DNA；保留外显子仍可能包含非翻译区。'), [(3, 'RNA与DNA的组成和方向性是转录基础')]), ('遗传密码与蛋白质翻译', '遗传信息', '蛋白质的生物合成', '核糖体按mRNA密码子顺序合成多肽，tRNA连接密码识别与氨基酸输送。密码的简并性表示多个密码子可指定同一氨基酸，不表示一个密码子可随意编码所有氨基酸。', ['能说明mRNA、tRNA和核糖体的分工。', '能区分密码简并性与无规则编码。'], Q('在翻译中，携带氨基酸并通过反密码子识别密码子的RNA是哪类？', 'tRNA', ['mRNA', 'rRNA', 'snRNA'], 'tRNA的适配作用将密码子识别与相应氨基酸连接起来。'), Q('某碱基替换使密码子改变，但所编码氨基酸不变，最直接体现哪种性质？', '遗传密码的简并性', ['每个密码子都能随机指定多种氨基酸', '任何碱基替换都必然改变阅读框', '编码相同氨基酸必须使用完全相同的密码子'], '多个密码子可指定同一氨基酸；同义变化也不意味着在所有情形下均无其他生物学影响。'), [(10, '成熟mRNA作为翻译信息模板')]), ('基因表达调控与分子检测原理', '分子医学方法', '基因表达调控；常用的分子生物学技术', '基因表达可在转录及转录后等多个层次调节。PCR扩增特定DNA区段需要引物等条件；检测到核酸仅说明在检测条件下存在相应靶标，需与其他证据联系解释。', ['能辨认表达调控的多个层次。', '能说明PCR检测结果的证据边界。'], Q('常规PCR扩增特定DNA片段时，用于界定目标区域的重要成分是什么？', '成对的特异性引物', ['能够与所有蛋白结合的抗体', '仅用作显色的非特异性核酸染料', '核糖体与对应的tRNA'], '引物与模板特定位点互补结合，提供延伸起点并帮助确定扩增范围。'), Q('在质量控制合格的核酸检测中检出某靶序列，哪种表述最严谨？', '检测条件下发现了相应核酸靶标，不能仅此证明活性或全部功能状态', ['一定证明所有来源细胞均存活', '一定证明靶序列已高水平表达为功能蛋白', '可以直接推出所有治疗结论'], '核酸存在、活性、蛋白表达和临床意义是不同层次，需结合检测对象和其他证据。'), [(9, 'PCR模拟模板依赖核酸合成的部分原理'), (11, '比较核酸与蛋白表达需了解信息传递', 'soft')])]
